/* Local-first v0.3 workspace. Model clocks show elapsed time, never invented progress. */
"use strict";
const $ = (q, root = document) => root.querySelector(q);
const $$ = (q, root = document) => [...root.querySelectorAll(q)];
const esc = value => String(value ?? "").replace(/[&<>"']/g, ch => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch]));
const ident = value => encodeURIComponent(String(value));
const list = value => Array.isArray(value) ? value : [];
const asText = value => value == null ? "" : Array.isArray(value) ? value.map(asText).join("；") : typeof value === "object" ? Object.entries(value).map(([k,v]) => `${k}：${asText(v)}`).join("；") : String(value);
const PAGE = 30;
const STATUS = {match:"符合",partial:"部分符合",mismatch:"不符合",missing:"產品未記載",uncertain:"待釐清"};
const RISK = {high:"高優先度",medium:"中優先度",low:"低優先度",unknown:"風險待評估",none:"未發現差異"};
const KIND = {requirement:"規範要求",specification:"產品規格",context:"背景／適用條件",unresolved:"待處理原文"};
const DECISION = {pending:"待確認",confirmed:"已確認",changed:"已修正",reopened:"已重新開啟"};
const PHASE = {queued:"已排入工作佇列",running:"執行中",extracting:"抽取獨立規格項目",extraction:"抽取獨立規格項目",screening:"檢查標準相關性與適用範圍",awaiting_selection:"初篩完成，等待確認標準範圍",comparing:"逐項檢查規格與證據",completed:"已完成",cancelled:"已停止，已儲存的進度會保留",interrupted:"工作中斷，可繼續未完成項目",failed:"工作未完成，請查看原因",preparing:"整理本次請求內容",waiting_model:"等待本機模型回覆",checking_response:"檢查模型回覆與原文證據",saving_result:"儲存結果與追溯紀錄",handling_error:"記錄無法完成的請求"};
const TITLES = {library:["建立你的標準文件庫","標準只需整理一次；每份產品都能沿用，逐項查核有據可循。"],product:["從一份產品，開始全庫分析","保留產品用途與適用情境，為每份標準留下相關性判斷。"],screening:["先確認，哪些標準值得檢查","所有標準預設納入；不確定的適用性保留給人工確認。"],results:["每個差異，都有回到原文的路","分開呈現符合狀態、風險優先度與證據缺口。"],exports:["讓結論和確認過程一起交付","保留這次分析的版本、原文、選取理由及每一次覆核。"]};
const state = {panel:"library",settings:{},selected:new Map(),library:[],products:[],product:null,document:null,items:[],item:null,split:false,analysis:null,result:null,screening:[],decisions:new Map(),monitor:null,pollTimer:null,pollController:null,pollEpoch:0,pollBusy:false,contactAt:0,serverAt:0,offline:"",renderError:"",offsets:{library:0,products:0,analyses:0,screening:0,results:0,items:0,extras:0,exports:0,audit:0,documentAudit:0},loadEpoch:{},reviewer:localStorage.getItem("specheck-reviewer") || ""};
function notify(message, error = false) { const box=$("#notice"); box.textContent=message; box.className=`notice${error?" error":""}`; box.hidden=false; const dialogs=$$("dialog[open]");const dialog=dialogs.at(-1);if(dialog){let local=$(".dialog-notice",dialog);if(!local){local=document.createElement("div");local.setAttribute("role","status");const heading=$(".dialog-heading",dialog);heading?.after(local);}local.className=`dialog-notice notice${error?" error":""}`;local.textContent=message;local.scrollIntoView({block:"nearest"});} }
function tag(label, kind="") { return `<span class="tag ${esc(kind)}">${esc(label)}</span>`; }
function empty(message) { return `<div class="empty">${esc(message)}</div>`; }
function time(value) { if (!value) return "尚未收到"; const d=new Date(value); return Number.isNaN(d.getTime()) ? "—" : d.toLocaleString("zh-TW",{month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",second:"2-digit",hour12:false}); }
function duration(value) { const s=Math.max(0,Math.floor(Number(value)||0)); return [Math.floor(s/3600),Math.floor(s/60)%60,s%60].map(n=>String(n).padStart(2,"0")).join(":"); }
function showDialog(id, show=true) { const dialog=$(`#${id}`); if(show&&!dialog.open) {$(".dialog-notice",dialog)?.remove();dialog.showModal();} if(!show&&dialog.open) dialog.close(); }
function rememberReviewer(value) { if(value.trim()) {state.reviewer=value.trim();localStorage.setItem("specheck-reviewer",state.reviewer);} }
function effective(row) { return ["confirmed","changed"].includes(row.review?.decision) ? row.review.final_status || row.status : row.status; }
function riskOf(row) { return row.review?.risk_level || row.risk?.level || row.risk?.risk_level || (typeof row.risk==="string"?row.risk:null) || "unknown"; }
async function api(path, options={}, timeout=30000) {
 const controller=new AbortController(); const external=options.signal;
 const abort=()=>controller.abort(); if(external) external.addEventListener("abort",abort,{once:true});
 const timer=setTimeout(abort,timeout);
 try { const headers={...(options.headers||{})}; if(options.body && !(options.body instanceof FormData)) headers["Content-Type"]="application/json";
  const response=await fetch(path,{...options,headers,signal:controller.signal});
  if(!response.ok) { let message=`請求失敗（${response.status}）`; try {const data=await response.json();message=typeof data.detail==="string"?data.detail:message;}catch{} throw new Error(message); }
  return await response.json();
 } catch(error) { if(error.name==="AbortError") throw new Error("本機服務未在時間內回覆，請確認啟動視窗仍在執行，再重試。"); throw error; }
 finally {clearTimeout(timer);if(external) external.removeEventListener("abort",abort);}
}
const post = (path, data={}) => api(path,{method:"POST",body:JSON.stringify(data)});
async function busy(button, action, caption="處理中…") { if(button?.disabled)return;const previous=button?.innerHTML;if(button){button.disabled=true;button.textContent=caption;}try{return await action();}catch(error){notify(error.message,true);throw error;}finally{if(button){button.disabled=false;button.innerHTML=previous;}} }
function handle(target,event,fn) { const element=typeof target==="string"?$(target):target;element.addEventListener(event,e=>{try{Promise.resolve(fn(e)).catch(error=>notify(error.message,true));}catch(error){notify(error.message,true);}}); }
function debounce(fn,ms=300) {let timer;return (...args)=>{clearTimeout(timer);timer=setTimeout(()=>Promise.resolve(fn(...args)).catch(e=>notify(e.message,true)),ms);};}
function pageQuery(key, extras={}) { return new URLSearchParams({offset:state.offsets[key],limit:PAGE,...extras}).toString(); }
function pager(selector, data, key) { const total=Number(data.total)||0,offset=Number(data.offset)||0,limit=Number(data.limit)||PAGE;$(selector).innerHTML=`<span>${total?`${offset+1}–${Math.min(offset+limit,total)}`:"0"} / ${total} 項</span><div class="actions"><button data-page="${key}" data-offset="${Math.max(0,offset-limit)}" ${offset<=0?"disabled":""}>上一頁</button><button data-page="${key}" data-offset="${offset+limit}" ${offset+limit>=total?"disabled":""}>下一頁</button></div>`; }
function requestStamp(key) {state.loadEpoch[key]=(state.loadEpoch[key]||0)+1;return state.loadEpoch[key];}
function currentStamp(key,stamp) {return state.loadEpoch[key]===stamp;}
function selectPanel(name) {state.panel=name;$$('[data-panel]').forEach(b=>{b.classList.toggle("active",b.dataset.panel===name);b.setAttribute("aria-current",b.dataset.panel===name?"step":"false");});$$('.panel').forEach(p=>p.hidden=p.id!==`panel-${name}`);$("#page-title").textContent=TITLES[name][0];$("#page-description").textContent=TITLES[name][1];if(name==="screening")return loadScreening();if(name==="results")return loadResults();if(name==="exports")return loadExports();}
function docStatus(doc) { if(doc.confirmed)return tag("已人工確認","confirmed");if(doc.index_status==="completed"||doc.index_status==="ready")return tag("抽取完成 · 待確認","pending");return tag(({pending:"尚未抽取",queued:"排隊中",extracting:"抽取中",running:"抽取中",failed:"抽取未完成",interrupted:"抽取中斷"})[doc.index_status]||"尚未抽取",doc.index_status); }
function renderDoc(doc, product=false) {return `<article class="document-row">${!product?`<input type="checkbox" data-select-doc="${esc(doc.id)}" aria-label="勾選 ${esc(doc.name)}" ${state.selected.has(doc.id)?"checked":""}>`:""}<span class="file-icon" aria-hidden="true">▤</span><div class="doc-main"><h3>${esc(doc.name)}</h3><p class="helper">${Number(doc.item_count)||0} 個項目 · ${Number(doc.unresolved_count)||0} 項待處理 · 版本 ${Number(doc.version)||1}</p></div>${docStatus(doc)}<div class="actions">${doc.job_id&&!doc.confirmed?`<button class="small" data-document-job="${esc(doc.job_id)}">查看進度</button>`:""}<button class="small" data-document="${esc(doc.id)}">查看／確認</button>${product?`<button class="small ${state.product?.id===doc.id?"primary":""}" data-use-product="${esc(doc.id)}" ${!doc.confirmed?"disabled":""}>${state.product?.id===doc.id?"已選取":"用於分析"}</button>`:""}</div></article>`;}
async function loadLibrary() {const stamp=requestStamp("library");const data=await api(`/api/v2/library?${pageQuery("library",{q:$("#library-search").value.trim()})}`);if(!currentStamp("library",stamp))return;state.library=list(data.items);for(const doc of state.library)if(state.selected.has(doc.id))state.selected.set(doc.id,doc);$("#library-list").innerHTML=state.library.map(d=>renderDoc(d)).join("")||empty("還沒有標準文件。從上方選擇一份或多份標準開始。");$("#library-count").textContent=`共 ${data.total||0} 份標準；抽取與確認後可跨產品重複使用。`;pager("#library-pagination",data,"library");renderSelected();}
function renderSelected() {$("#library-selected").textContent=`已選 ${state.selected.size} 份`;$("#library-extract").disabled=!state.selected.size;$("#library-confirm").disabled=!state.selected.size;$("#library-select-page").checked=!!state.library.length&&state.library.every(d=>state.selected.has(d.id));$("#library-select-page").indeterminate=state.library.some(d=>state.selected.has(d.id))&&!$("#library-select-page").checked;}
async function loadProducts() {const stamp=requestStamp("products");const data=await api(`/api/v2/products?${pageQuery("products",{q:$("#product-search").value.trim()})}`);if(!currentStamp("products",stamp))return;state.products=list(data.items);$("#product-list").innerHTML=state.products.map(d=>renderDoc(d,true)).join("")||empty("尚未上傳產品規格。");pager("#product-pagination",data,"products");if(state.product){const fresh=state.products.find(d=>d.id===state.product.id);if(fresh)chooseProduct(fresh,false);}}
function chooseProduct(doc,render=true) {state.product=doc;$("#selected-product").textContent=`本次產品：${doc.name}${doc.confirmed?" · 已確認":" · 尚待確認"}`;if(!$("#analysis-name").value)$("#analysis-name").value=`${doc.name} · 標準風險分析`;if(render)$("#product-list").innerHTML=state.products.map(d=>renderDoc(d,true)).join("");}
async function upload(kind, input, button) {const files=[...input.files];if(!files.length)return;await busy(button,async()=>{const errors=[];let last=null;for(let i=0;i<files.length;i++){button.textContent=`上傳 ${i+1} / ${files.length}…`;try{const body=new FormData();body.append("file",files[i]);last=await api(`/api/v2/${kind}`,{method:"POST",body},120000);if(kind==="library")state.selected.set(last.id,last);}catch(error){errors.push(`${files[i].name}：${error.message}`);}}input.value="";await(kind==="library"?loadLibrary():loadProducts());notify(`已上傳 ${files.length-errors.length} / ${files.length} 份文件。${errors.length?`\n${errors.join("\n")}`:"請接著抽取獨立項目並確認原文。"}`,!!errors.length);if(kind==="products"&&last)await openDocument(last.id);},"上傳中…");}
async function openDocument(id) {const stamp=requestStamp("document");const doc=await api(`/api/v2/documents/${ident(id)}`);if(!currentStamp("document",stamp))return;state.document=doc;state.offsets.items=0;state.offsets.documentAudit=0;$("#item-kind").value="";$("#item-search").value="";$("#source-search").value="";$("#document-ack").checked=false;$("#document-note").value="";$("#document-reviewer").value=state.reviewer;$("#metadata-reviewer").value=state.reviewer;$("#document-audit").innerHTML="";renderDocument();showDialog("document-dialog");await loadItems();if(doc.job_id&&doc.index_status!=="ready"){const job=await api(`/api/v2/jobs/${ident(doc.job_id)}`);if(state.document?.id===doc.id)setMonitor("job",job);}}
function renderDocument() {const doc=state.document;if(!doc)return;$("#document-external").hidden=doc.role!=="standard";$("#document-external").disabled=["queued","running"].includes(doc.index_status);$("#document-job").hidden=!doc.job_id;$("#document-name").textContent=doc.name;$("#document-role").textContent=doc.role==="product"||doc.kind==="product"?"產品規格":"標準與技術規範";$("#document-status").textContent=`${doc.confirmed?"已人工確認":"尚待人工確認"} · ${Number(doc.item_count)||0} 個獨立項目 · ${Number(doc.unresolved_count)||0} 個待處理項目 · 版本 ${doc.version}`;const sourceInfo=[doc.import_source?.url?`下載來源：${doc.import_source.url}`:"",doc.source_url?`外部填報的原規範來源：${doc.source_url}`:""].filter(Boolean);$("#document-import-source").textContent=sourceInfo.join("\n");$("#document-import-source").hidden=!sourceInfo.length;const warnings=[...list(doc.warnings),...list(doc.extraction_warnings)].map(asText);$("#document-warnings").textContent=warnings.join("\n");$("#document-warnings").hidden=!warnings.length;$("#document-original").textContent=doc.source_kind==="external_transcription"?"下載原始成果 JSON":"下載原始檔";$("#document-original").href=`/api/v2/documents/${ident(doc.id)}/original`;$("#document-extract").textContent=doc.item_count?"重新抽取項目（保留歷程）":"抽取獨立項目";$("#document-extract").disabled=["running","extracting","queued"].includes(doc.index_status);for(const k of ["category","version","region","scope"])$(`#metadata-${k}`).value=doc.metadata?.[k]||"";$("#document-confirm").disabled=doc.external_coverage?.status==="partial"||doc.confirmed||!["completed","ready"].includes(doc.index_status);renderSources();}
function renderSources(focus="") {const q=$("#source-search").value.trim().toLocaleLowerCase();$("#document-sources").innerHTML=list(state.document?.blocks).filter(b=>!q||asText(b.text).toLocaleLowerCase().includes(q)).map(b=>`<article class="source-block ${b.id===focus?"highlight":""}" data-source="${esc(b.id)}"><small>${esc(b.location||b.label||b.id)} · ${esc(b.id)}</small><p>${esc(b.text)}</p></article>`).join("")||empty("沒有符合條件的原文。");if(focus){const block=$$('.source-block').find(b=>b.dataset.source===focus);block?.scrollIntoView({block:"nearest",behavior:"instant"});}}
function itemValues(item) {const fields=[["數值",item.value],["單位",item.unit],["比較條件",item.operator],["適用條件",item.conditions],["例外",item.exceptions],["測試方法",item.test_method],["重要性依據",item.criticality_basis]];return `${list(item.context_evidence).length?`<details><summary>跨章條件原文（外部萃取參照）</summary>${item.context_evidence.map(r=>`<blockquote><cite>${esc(r.block_id)}</cite>${esc(r.quote)}</blockquote>`).join("")}</details>`:""}<dl class="item-values">${fields.filter(([,v])=>asText(v)).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(asText(v))}</dd>`).join("")}</dl>`;}
async function loadItems() {if(!state.document)return;const id=state.document.id,stamp=requestStamp("items");const data=await api(`/api/v2/documents/${ident(id)}/items?${pageQuery("items",{kind:$("#item-kind").value,q:$("#item-search").value.trim()})}`);if(state.document?.id!==id||!currentStamp("items",stamp))return;state.items=list(data.items);if(data.document)state.document={...state.document,...data.document};$("#document-items").innerHTML=state.items.map(i=>`<article class="item-card">${tag(KIND[i.kind]||i.kind,i.kind)} ${tag(RISK[i.criticality]||"重要性待確認",i.criticality)}<h4>${esc(i.name||i.parameter||"未命名項目")}</h4>${itemValues(i)}<p>${esc(i.quote)}</p><div class="actions"><button class="small" data-source-item="${esc(i.id)}">查看來源</button><button class="small" data-edit-item="${esc(i.id)}">修改項目</button><button class="small" data-split-item="${esc(i.id)}">拆成多項</button></div></article>`).join("")||empty("尚無項目，請先抽取；或變更篩選條件。");pager("#items-pagination",data,"items");}
async function refreshDocument() {if(!state.document)return;const id=state.document.id,doc=await api(`/api/v2/documents/${ident(id)}`);if(state.document?.id!==id)return;state.document=doc;renderDocument();await loadItems();await Promise.all([loadLibrary(),loadProducts()]);}
const EDIT_FIELDS=[["name","項目名稱"],["parameter","規格參數"],["value","數值／文字要求"],["unit","單位"],["operator","比較方式（例如 ≥、範圍）"],["conditions","適用條件"],["exceptions","例外"],["test_method","測試方法"],["criticality_basis","重要性依據"]];
function editorMarkup(item,index) {return `<fieldset class="item-editor"><legend>項目 ${index+1}</legend><div class="field-grid">${EDIT_FIELDS.map(([k,label])=>`<label>${label}<input data-field="${k}" value="${esc(asText(item[k]))}" ${k==="name"?"required":""}></label>`).join("")}<label>種類<select data-field="kind">${Object.entries(KIND).map(([k,v])=>`<option value="${k}" ${item.kind===k?"selected":""}>${v}</option>`).join("")}</select></label><label>重要性<select data-field="criticality">${["unknown","high","medium","low"].map(k=>`<option value="${k}" ${item.criticality===k?"selected":""}>${RISK[k]}</option>`).join("")}</select></label></div><label>來源原文區塊<select data-field="block_id" disabled>${list(state.document.blocks).filter(b=>b.id===item.block_id).map(b=>`<option value="${esc(b.id)}" ${item.block_id===b.id?"selected":""}>${esc(b.location||b.id)} · ${esc(String(b.text||"").slice(0,90))}</option>`).join("")}</select></label><label>精確原文引文<textarea data-field="quote" rows="3" required>${esc(item.quote)}</textarea></label></fieldset>`;}
function openItem(id,split=false) {state.item=state.items.find(i=>i.id===id);if(!state.item)return;state.split=split;$("#item-dialog-title").textContent=split?"將複合要求拆成獨立項目":"修改獨立項目";$("#item-editors").innerHTML=editorMarkup(state.item,0)+(split?editorMarkup({...state.item,name:""},1):"");$("#item-add").hidden=!split;$("#item-reviewer").value=state.reviewer;$("#item-note").value="";showDialog("item-dialog");}
function readEditors() {return $$(".item-editor").map(editor=>Object.fromEntries($$("[data-field]",editor).map(f=>[f.dataset.field,f.value.trim()])));}
function isActive(m) {return !!m&&["queued","running","screening","comparing","extracting"].includes(m.data.status);}
function setMonitor(kind,data) {stopPoll();state.monitor={kind,id:data.id,data};state.offline="";state.renderError="";recordContact(data.server_time);renderMonitor();schedulePoll(0);}
function recordContact(serverTime) {state.contactAt=Date.now();state.serverAt=Date.parse(serverTime)||Date.now();}
function stopPoll() {state.pollEpoch++;clearTimeout(state.pollTimer);state.pollController?.abort();state.pollController=null;state.pollBusy=false;}
function schedulePoll(delay=1800) {clearTimeout(state.pollTimer);if(state.monitor&&(isActive(state.monitor)||state.offline||state.renderError))state.pollTimer=setTimeout(pollMonitor,delay);}
function renderMonitor() {const m=state.monitor;$("#execution").hidden=!m;if(!m)return;const data=m.data,p=data.progress||{},live=isActive(m),stale=live&&Date.now()-state.contactAt>12000,offline=!!state.offline||stale;$("#execution").dataset.offline=String(offline);$("#execution-spinner").dataset.active=String(live&&!offline);const stage=p.stage||data.phase||data.status;const terminal=!live;const headline=offline?"現況連線中斷，等待重新確認":`${PHASE[terminal?data.status:stage]||PHASE[data.status]||"執行中"}${state.renderError?" · 清單更新未完成":""}`;if($("#execution-title").textContent!==headline)$("#execution-title").textContent=headline;$("#execution-document").textContent=[data.document_name||p.document_name||p.standard_name||data.name||"本機分析工作",p.item_name||p.location||""].filter(Boolean).join(" · ");const now=terminal?(Date.parse(p.finished_at)||Date.parse(p.updated_at)||state.serverAt):offline?state.serverAt:state.serverAt+(Date.now()-state.contactAt);$("#execution-elapsed").textContent=p.started_at?duration((now-Date.parse(p.started_at))/1000):"00:00:00";$("#execution-wait").textContent=p.request_started_at?duration((now-Date.parse(p.request_started_at))/1000):"—";$("#execution-requests").textContent=Number(p.requests_completed)||0;$("#execution-response").textContent=p.last_response_at?time(p.last_response_at):"尚未收到";const completed=Number(data.completed??p.completed??data.counts?.completed??0)||0,total=Number(data.total??p.total??data.counts?.total??0)||0;$("#execution-count").textContent=`已處理並儲存 ${completed} / ${total||"待計算"} 項${total?` · ${Math.min(100,Math.floor(completed/total*100))}%`:""}`;$("#execution-progress").max=total||1;$("#execution-progress").value=Math.min(completed,total||1);$("#execution-window").textContent=p.window_total?`目前項目的分段 ${p.window_index||0} / ${p.window_total}`:"";$("#execution-note").textContent=offline?"已停止動畫與本地計時。這不代表模型已停止；畫面保留最後一次確認的狀態，恢復連線後會更新。":p.cancel_requested?"已送出停止指令；目前模型請求回覆或逾時後停止，已儲存結果會保留。":data.error?asText(data.error):data.status==="awaiting_selection"?"初篩已完成。請在相關標準中確認選取及排除理由，再開始逐項比對。":stage==="waiting_model"?`正在等待本機模型回覆。完成數仍可能暫時不變；每次請求最長等待 ${p.timeout_seconds||state.settings.timeout||600} 秒。計時器只代表已等待時間。`:terminal?"已儲存的項目、原文與人工確認紀錄可繼續查看。":"系統會在實際收到回覆及儲存項目後更新；不以動畫推定模型內部進度。";$("#execution-connection").textContent=offline?`${state.offline||"超過 12 秒未確認連線"} 自動重試中，也可按「更新現況」。`:state.renderError?`執行狀態已更新；${state.renderError}。可按「更新現況」重試清單。`:`本機服務最近確認：${time(new Date(state.contactAt).toISOString())}。服務回覆不代表模型已完成推論。`;$("#job-cancel").hidden=!live;$("#job-cancel").disabled=!!p.cancel_requested;$("#job-resume").hidden=!["cancelled","interrupted","failed"].includes(data.status);const events=list(p.events),eventSignature=m.id+JSON.stringify(events);if(state.eventSignature!==eventSignature){state.eventSignature=eventSignature;$("#execution-events").innerHTML=events.slice(-30).map(e=>`<li><time>${esc(time(e.at||e.timestamp))}</time>${esc(e.message||PHASE[e.stage]||e.stage)}</li>`).join("")||"<li>尚無執行事件。</li>";}}
async function pollMonitor() {if(!state.monitor||state.pollBusy)return;const epoch=state.pollEpoch,m=state.monitor,id=m.id;state.pollBusy=true;const controller=new AbortController();state.pollController=controller;let failed=false,gotStatus=false;const current=()=>epoch===state.pollEpoch&&state.monitor?.id===id;try{const data=await api(`/api/v2/${m.kind==="analysis"?"analyses":"jobs"}/${ident(id)}`,{signal:controller.signal},8000);if(!current())return;const old=m.data,changed=old.status!==data.status||old.completed!==data.completed||old.progress?.completed!==data.progress?.completed;state.monitor.data=data;state.offline="";recordContact(data.server_time);gotStatus=true;if(m.kind==="analysis"&&state.analysis?.id===id)state.analysis=data;renderMonitor();if(changed||state.renderError){state.renderError="";if(m.kind==="analysis"){renderAnalysisMeta();if(state.panel==="screening")await loadScreening();if(state.panel==="results")await loadResults();if(!isActive(state.monitor))await loadAnalyses();}else if(!isActive(state.monitor)){await Promise.all([loadLibrary(),loadProducts()]);if(state.document&&$("#document-dialog").open)await refreshDocument();}}}catch(error){if(!current())return;failed=true;if(gotStatus)state.renderError=error.message;else state.offline=error.message;renderMonitor();}finally{if(current()){state.pollBusy=false;state.pollController=null;renderMonitor();schedulePoll(failed?5000:1800);}}}
async function controlJob(action,button) {const m=state.monitor;if(!m)return;stopPoll();await busy(button,async()=>{const data=await post(`/api/v2/${m.kind==="analysis"?"analyses":"jobs"}/${ident(m.id)}/${action}`);if(state.monitor?.id!==m.id)return;setMonitor(m.kind,data);if(m.kind==="analysis"){state.analysis=data;renderAnalysisMeta();}notify(action==="cancel"?"停止要求已記錄；目前模型請求回覆或逾時後停止。":"已繼續未完成工作。");}).finally(()=>schedulePoll());}
async function loadAnalyses() {const stamp=requestStamp("analyses"),data=await api(`/api/v2/analyses?${pageQuery("analyses")}`);if(!currentStamp("analyses",stamp))return;$("#analysis-list").innerHTML=list(data.items).map(a=>`<article class="document-row"><span class="file-icon" aria-hidden="true">↗</span><div class="doc-main"><h3>${esc(a.name||a.product_name)}</h3><p class="helper">${esc(a.product_name||"")} · ${esc(time(a.created_at))} · ${a.comparison_mode==="exhaustive"?"完整比對":"候選比對"}</p></div>${tag(PHASE[a.status]||a.status,a.status)}<button class="small" data-analysis="${esc(a.id)}">開啟分析 →</button></article>`).join("")||empty("尚無分析。選擇已確認的產品並填寫用途後即可開始。");pager("#analyses-pagination",data,"analyses");}
async function openAnalysis(id) {if(state.decisions.size&&!window.confirm("有尚未儲存的標準選取，開啟其他分析會清除這些修改。要繼續嗎？"))return;const stamp=requestStamp("analysis"),data=await api(`/api/v2/analyses/${ident(id)}`);if(!currentStamp("analysis",stamp))return;state.analysis=data;state.decisions.clear();for(const key of ["screening","results","extras","exports","audit"])state.offsets[key]=0;$("#selection-reviewer").value=state.reviewer;$("#selection-note").value="";$("#extras-list").innerHTML="";$("#analysis-audit").innerHTML="";$("#result-status").value="";$("#result-risk").value="";$("#result-review").value="";$("#result-search").value="";setMonitor("analysis",data);renderAnalysisMeta();await selectPanel(["completed","comparing"].includes(data.status)?"results":"screening");}
function coverageText(c) {if(!c)return "";const labels={standards_total:"標準總數",total_standards:"標準總數",total_items:"預計比對項目",compared:"已完成項目",unresolved_items:"待處理原文項目",standards_selected:"納入標準",standards_excluded:"排除標準",selected_standards:"納入標準",excluded_standards:"排除標準",requirements_total:"規範要求",requirements_completed:"已完成要求",product_items_total:"產品項目",product_unresolved:"產品待處理項目",standard_unresolved:"標準待處理項目",unresolved_count:"待處理原文",context_items:"背景／條件項目",items_total:"項目總數",items_completed:"已完成項目",results_total:"已儲存結果",screened:"已初篩標準",standards_screened:"已初篩標準",matched_product_items:"已有對應產品項目"};const parts=Object.entries(labels).filter(([k])=>c[k]!=null).map(([k,label])=>`${label} ${asText(c[k])}`);if(c.comparison_mode)parts.push(c.comparison_mode==="exhaustive"?"完整產品項目比對":"候選項目比對");if(c.selected_scope_complete!=null)parts.push(c.selected_scope_complete?"所選範圍已完整掃描":"所選範圍尚未完整掃描");if(c.coverage_complete===false)parts.push("仍有排除標準、未完成項目或未全量掃描的範圍");return parts.join(" · ");}
function renderAnalysisMeta() {const a=state.analysis;if(!a)return;const label=`${a.name||a.product_name} · ${PHASE[a.status]||a.status} · ${a.comparison_mode==="exhaustive"?"完整產品項目比對":"候選項目比對"}`;for(const key of ["screening","results","exports"])$(`#${key}-analysis`).textContent=label;$("#selection-form").hidden=a.status!=="awaiting_selection";$("#screening-coverage").textContent=coverageText(a.coverage);$("#result-coverage").textContent=coverageText(a.coverage);const counts=a.counts||{},statuses=counts.statuses||counts.status||counts;const risks=counts.risks||counts.risk||{};$("#result-stats").innerHTML=[["已儲存項目",counts.results??counts.total??counts.completed??a.completed??0],["高優先度",risks.high??counts.high??counts.high_risk??0],["待補證據",statuses.missing??0],["待人工確認",counts.pending??counts.review_pending??0]].map(([label,value])=>`<div><span>${esc(label)}</span><strong>${Number(value)||0}</strong></div>`).join("");}
async function loadScreening() {if(!state.analysis){$("#screening-list").innerHTML=empty("先建立分析；初篩完成後會列出每份標準的相關理由。");return;}const id=state.analysis.id,stamp=requestStamp("screening");const data=await api(`/api/v2/analyses/${ident(id)}/screening?${pageQuery("screening")}`);if(state.analysis?.id!==id||!currentStamp("screening",stamp))return;state.screening=list(data.items);const editable=state.analysis.status==="awaiting_selection";const rel={high:"高度相關",medium:"可能相關",low:"低相關",unknown:"相關性待確認",related:"相關",unrelated:"可能無關"},app={applicable:"適用",not_applicable:"可能不適用",unknown:"適用性待確認",uncertain:"適用性待確認",likely:"可能適用",conditional:"有條件適用"};$("#screening-list").innerHTML=state.screening.map(s=>{const change=state.decisions.get(s.standard_id),selected=change?.selected??s.selected,reason=change?.reason??s.review?.note??s.review?.reason??s.exclusion_reason??"";return `<article class="screen-card"><div class="row spread"><label class="check"><input data-screen-select="${esc(s.standard_id)}" type="checkbox" ${selected!==false?"checked":""} ${editable?"":"disabled"}><span>${esc(s.standard_name)}</span></label>${tag(selected!==false?"納入比對":"已排除",selected!==false?"confirmed":"unknown")}</div><div class="meta">${tag(rel[s.relevance]||asText(s.relevance)||"相關性待確認",s.relevance)}${tag(app[s.applicability]||asText(s.applicability)||"適用性待確認",s.applicability)}</div><p>${esc(asText(s.reason))}</p>${s.evidence?.length?`<details><summary>查看初篩依據</summary>${list(s.evidence).map(e=>`<div class="screen-evidence"><cite>${esc(e.document_id===state.analysis.product_id?state.analysis.product_name:s.standard_name)} · ${esc(e.location||e.block_id)}</cite><blockquote>${esc(e.quote)}</blockquote></div>`).join("")}</details>`:""}${s.warnings?.length?`<p class="helper">待確認：${esc(asText(s.warnings))}</p>`:""}<label class="reason" ${selected!==false?"hidden":""}>排除理由（必填）<input data-screen-reason="${esc(s.standard_id)}" value="${esc(reason)}" ${editable?"":"disabled"} placeholder="例如：僅適用航空設備，本產品為固定式地面設備"></label></article>`;}).join("")||empty("初篩結果會在儲存後陸續出現。可從上方查看實際模型請求現況。");pager("#screening-pagination",data,"screening");renderAnalysisMeta();}
function updateSelection(id,selected,reason) {const old=state.screening.find(s=>s.standard_id===id),change=state.decisions.get(id)||{standard_id:id,selected:old?.selected!==false,reason:old?.review?.note||old?.review?.reason||old?.exclusion_reason||""};if(selected!==undefined)change.selected=selected;if(reason!==undefined)change.reason=reason;state.decisions.set(id,change);$("#selection-dirty").textContent=`有 ${state.decisions.size} 份標準的選取尚未儲存。排除理由會保留在報告中。`;}
async function saveSelection() {if(!state.analysis)return;const reviewer=$("#selection-reviewer").value.trim();if(!reviewer)throw new Error("請填寫範圍確認人員。");for(const d of state.decisions.values())if(!d.selected&&!d.reason.trim())throw new Error("排除標準前，請填寫每份標準的排除理由。");const a=state.analysis;const data=await post(`/api/v2/analyses/${ident(a.id)}/selection`,{expected_version:a.version,reviewer,note:$("#selection-note").value.trim(),decisions:state.decisions.size?[...state.decisions.values()]:state.screening.map(s=>({standard_id:s.standard_id,selected:s.selected!==false,reason:s.review?.note||""}))});state.analysis=data;state.decisions.clear();rememberReviewer(reviewer);if(state.monitor?.id===a.id)state.monitor.data=data;$("#selection-dirty").textContent="選取與理由已儲存。";await loadScreening();return data;}
async function loadResults() {if(!state.analysis){$("#results-list").innerHTML=empty("開啟分析後，可在此逐項查看差異及風險。");return;}const id=state.analysis.id,stamp=requestStamp("results"),data=await api(`/api/v2/analyses/${ident(id)}/results?${pageQuery("results",{status:$("#result-status").value,risk:$("#result-risk").value,review:$("#result-review").value,q:$("#result-search").value.trim()})}`);if(state.analysis?.id!==id||!currentStamp("results",stamp))return;$("#results-list").innerHTML=list(data.items).map(r=>`<article class="result-card"><div class="result-main"><div class="result-meta">${esc(r.standard_name)} · ${esc(r.location||r.item?.location||"")}</div><h3>${esc(r.item?.name||r.item?.parameter||r.requirement||"規範項目")}</h3><div class="actions">${tag(STATUS[effective(r)]||"待釐清",effective(r))}${tag(RISK[riskOf(r)]||"風險待評估",riskOf(r))}</div><p>${esc(asText(r.differences?.length?r.differences:r.explanation)||"開啟項目查看證據與判定。")}</p></div><div class="result-actions">${tag(DECISION[r.review?.decision]||"待確認",r.review?.decision||"pending")}<button data-result="${esc(r.id)}" class="small">檢視證據與覆核 →</button></div></article>`).join("")||empty(state.analysis.status==="awaiting_selection"?"請先確認標準範圍並開始逐項比對。":"尚無符合條件的已儲存項目。可調整篩選或稍後更新。");pager("#results-pagination",data,"results");renderAnalysisMeta();}
async function openResult(id) {if(!state.analysis)return;const analysisId=state.analysis.id,stamp=requestStamp("result"),r=await api(`/api/v2/analyses/${ident(analysisId)}/results/${ident(id)}`);if(state.analysis?.id!==analysisId||!currentStamp("result",stamp))return;state.result=r;$("#result-document").textContent=`${r.standard_name||""} · ${r.location||r.item?.location||""}`;$("#result-name").textContent=r.item?.name||r.item?.parameter||"規範項目";$("#result-labels").innerHTML=tag(`目前：${STATUS[effective(r)]||"待釐清"}`,effective(r))+tag(RISK[riskOf(r)]||"風險待評估",riskOf(r))+tag(`AI 原始判定：${STATUS[r.status]||r.status}`)+tag(DECISION[r.review?.decision]||"待確認",r.review?.decision);$("#result-item").innerHTML=itemValues(r.item||{});$("#result-requirement").textContent=r.item?.quote||r.requirement||"";$("#result-evidence").innerHTML=list(r.evidence).map(e=>`<div class="quote"><cite>${esc(e.location||e.block_id||"產品原文")}</cite><blockquote>${esc(e.quote)}</blockquote>${e.text?`<details><summary>完整來源區塊</summary><p>${esc(e.text)}</p></details>`:""}</div>`).join("")||'<p class="helper">本項未找到可驗證的產品原文證據。需要補文件、測試資料或人工確認。</p>';$("#result-reason").innerHTML=`<p>${esc(r.explanation)}</p>${list(r.differences).length?`<ul>${r.differences.map(d=>`<li>${esc(asText(d))}</li>`).join("")}</ul>`:""}${list(r.warnings).length?`<p class="helper">${esc(asText(r.warnings))}</p>`:""}`;const risk=r.risk||{};$("#result-risk-reason").innerHTML=`<p><strong>風險判定依據：</strong>${esc(asText(risk.reason||risk.basis||risk.rationale)||"未提供充分依據，請人工判斷。")}</p>${risk.missing_evidence||risk.suggested_action||risk.action?`<p>待補資料／建議確認：${esc(asText(risk.missing_evidence||risk.suggested_action||risk.action))}</p>`:""}`;$("#result-retrieval").textContent=`比對覆蓋：${r.retrieval?.mode==="exhaustive"?"完整產品項目":"候選產品項目"}。${r.retrieval?.reason||r.retrieval?.note||"未建立對應不代表規範沒有要求，仍需檢查篩選與來源。"}`;$("#review-decision").value="confirmed";$("#review-status").value=effective(r)||"uncertain";$("#review-risk").value=riskOf(r);$("#review-reviewer").value=state.reviewer;$("#review-note").value="";renderReviewDecision();$("#review-history").innerHTML=renderAudit(r.history||[]);showDialog("result-dialog");}
function renderReviewDecision() {if($("#review-decision").value==="confirmed"&&state.result)$("#review-status").value=state.result.status;$("#review-status").disabled=$("#review-decision").value!=="changed";$("#review-risk").disabled=$("#review-decision").value==="reopened";}
function renderAudit(rows) {const actions={link_imported:"從連結匯入規範",link_import_reused:"從連結重用規範",standard_package_imported:"匯入外網完整成果",standard_package_reused:"重用外網完整成果",external_package_created:"建立外部萃取包",external_batch_imported:"匯入外部萃取批次",external_items_activated:"套用外部萃取項目",items_extracted:"抽取獨立項目",items_confirmed:"確認抽取項目",item_changed:"修改項目",standard_selected:"確認標準選取",analysis_created:"建立全庫分析",screening_completed:"完成相關性初篩",comparison_started:"開始逐項比對",comparison_completed:"完成逐項比對",result_reviewed:"人工覆核結果",report_exported:"封存匯出報告",document_uploaded:"上傳文件",job_resumed:"繼續工作",job_cancelled:"停止工作",created:"建立",confirmed:"確認",changed:"修正",reopened:"重新開啟",item_updated:"修改項目",item_split:"拆分項目",document_confirmed:"確認文件",selection:"確認選取",extracted:"抽取項目",metadata_updated:"修改文件資訊"};return list(rows).map(e=>`<article class="history-event"><strong>${esc(e.reviewer||e.actor||"系統")} · ${esc(actions[e.decision||e.action]||e.action||e.decision||e.event||"紀錄")}</strong><small>${esc(time(e.at||e.created_at||e.timestamp||e.updated_at))}${e.version!=null?` · 版本 ${Number(e.version)}`:""}</small>${e.final_status?`<p>${esc(STATUS[e.final_status]||e.final_status)}${e.risk_level?` · ${esc(RISK[e.risk_level]||e.risk_level)}`:""}</p>`:""}<p>${esc(e.note||e.reason||e.message||"")}</p></article>`).join("")||'<p class="helper">尚無人工修改紀錄。</p>';}
async function loadExtras() {if(!state.analysis)return;const id=state.analysis.id,stamp=requestStamp("extras"),data=await api(`/api/v2/analyses/${ident(id)}/product-extras?${pageQuery("extras")}`);if(state.analysis?.id!==id||!currentStamp("extras",stamp))return;$("#extras-coverage").textContent=data.coverage_complete?"本次比對已完成；候選篩選與適用範圍仍限制此清單的解讀。":"比對覆蓋尚未完成；這是暫時的未對應清單。";$("#extras-list").innerHTML=list(data.items).map(raw=>{const i=raw.item||raw;return `<article class="item-card"><h4>${esc(i.name||i.parameter||"產品項目")}</h4>${itemValues(i)}<p>${esc(i.quote)}</p><small>${esc(i.location||i.block_id||"")}</small></article>`;}).join("")||empty("目前沒有列出的未對應產品項目。");pager("#extras-pagination",data,"extras");}
async function loadExports() {if(!state.analysis){$("#exports-list").innerHTML=empty("先開啟分析，再下載及封存報告。");return;}const id=state.analysis.id,stamp=requestStamp("exports"),data=await api(`/api/v2/analyses/${ident(id)}/exports?${pageQuery("exports")}`);if(state.analysis?.id!==id||!currentStamp("exports",stamp))return;$("#exports-list").innerHTML=list(data.items||data).map(e=>`<article class="document-row"><div class="doc-main"><h3>${esc(e.filename||e.name||e.format?.toUpperCase()||"報告")}</h3><p class="helper">${esc(time(e.created_at))}${e.size||e.size_bytes?` · ${Number(e.size||e.size_bytes)} bytes`:""}</p><p class="hash">SHA256 ${esc(e.sha256||"")}</p></div><a class="button small" href="/api/exports/${ident(e.id)}/download">下載封存版本 ↓</a></article>`).join("")||empty("還沒有封存報告。上方任一格式下載後，會在這裡保留當時版本。");pager("#exports-pagination",data,"exports");renderAnalysisMeta();}
async function downloadExport(format,button) {if(!state.analysis)throw new Error("請先開啟一個分析。");await busy(button,async()=>{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),120000);let response;try{response=await fetch(`/api/v2/analyses/${ident(state.analysis.id)}/export?format=${ident(format)}`,{signal:controller.signal});}catch(error){throw new Error(error.name==="AbortError"?"報告產生超過 120 秒，請稍後重試或先查看已封存報告。":error.message);}finally{clearTimeout(timer);}if(!response.ok){let message="報告產生失敗";try{message=(await response.json()).detail||message;}catch{}throw new Error(message);}const blob=await response.blob(),url=URL.createObjectURL(blob),anchor=document.createElement("a");anchor.href=url;anchor.download=`規格比對報告-${state.analysis.id.slice(0,8)}.${format}`;document.body.append(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);await loadExports();notify("報告已下載，並封存這次的分析與覆核狀態。");},"產生報告中…");}
function openSettings() {const s=state.settings;$("#setting-base").value=s.base_url||"http://127.0.0.1:1234/v1";$("#setting-model").value=s.model||"";$("#setting-key").value="";$("#setting-clear-key").checked=false;$("#setting-temperature").value=s.temperature??0;$("#setting-tokens").value=s.max_tokens??1800;$("#setting-timeout").value=s.timeout??600;$("#setting-context").value=s.context_chars??6000;$("#setting-structured").checked=s.structured_output!==false;$("#connection-result").textContent=s.has_api_key?"已有儲存的金鑰，留空即可保留。":"尚未測試本次連線。";showDialog("settings-dialog");}
function settingsInput() {return {base_url:$("#setting-base").value.trim(),model:$("#setting-model").value.trim(),api_key:$("#setting-key").value,clear_api_key:$("#setting-clear-key").checked,temperature:Number($("#setting-temperature").value),max_tokens:Number($("#setting-tokens").value),timeout:Number($("#setting-timeout").value),context_chars:Number($("#setting-context").value),structured_output:$("#setting-structured").checked};}
