 handle(document,"click",async e=>{const button=e.target.closest("button,a");if(!button)return;if(button.dataset.close){e.preventDefault();showDialog(button.dataset.close,false);return;}if(button.dataset.panel){await selectPanel(button.dataset.panel);return;}if(button.dataset.documentJob){await showDocumentJob(button.dataset.documentJob);return;}if(button.dataset.document){await busy(button,()=>openDocument(button.dataset.document));return;}if(button.dataset.useProduct){chooseProduct(state.products.find(d=>d.id===button.dataset.useProduct));return;}if(button.dataset.analysis){await busy(button,()=>openAnalysis(button.dataset.analysis));return;}if(button.dataset.page){state.offsets[button.dataset.page]=Number(button.dataset.offset);await({library:loadLibrary,products:loadProducts,analyses:loadAnalyses,items:loadItems,screening:loadScreening,results:loadResults,extras:loadExtras,exports:loadExports,audit:loadAnalysisAudit,documentAudit:loadDocumentAudit}[button.dataset.page])();return;}if(button.dataset.sourceItem){const item=state.items.find(i=>i.id===button.dataset.sourceItem);$("#source-search").value="";renderSources(item?.block_id);return;}if(button.dataset.editItem){openItem(button.dataset.editItem);return;}if(button.dataset.splitItem){openItem(button.dataset.splitItem,true);return;}if(button.dataset.result){await busy(button,()=>openResult(button.dataset.result));return;}if(button.dataset.export){await downloadExport(button.dataset.export,button);}});
 handle(document,"change",e=>{const target=e.target;if(target.dataset.selectDoc){const doc=state.library.find(d=>d.id===target.dataset.selectDoc);if(target.checked)state.selected.set(doc.id,doc);else state.selected.delete(doc.id);renderSelected();}if(target.dataset.screenSelect){updateSelection(target.dataset.screenSelect,target.checked);const card=target.closest(".screen-card");$("label.reason",card).hidden=target.checked;const status=$(".row>.tag",card);status.textContent=target.checked?"納入比對":"已排除";status.className=`tag ${target.checked?"confirmed":"unknown"}`;}});
