 handle("#library-extract","click",e=>busy(e.currentTarget,async()=>{const job=await post("/api/v2/library/extract",{document_ids:[...state.selected.keys()]});setMonitor("job",job);notify("已開始抽取勾選的標準。可以從執行現況查看文件與模型請求狀態。");await loadLibrary();}));
 handle("#library-confirm","click",async()=>{if(!state.selected.size)return;await refreshSelectedSummaries();const pending=[...state.selected.values()].filter(d=>d.index_status!=="ready").length;if(pending)throw new Error(`勾選文件還有 ${pending} 份尚未完成抽取，請先完成或調整選取。`);const unresolved=[...state.selected.values()].reduce((sum,d)=>sum+(Number(d.unresolved_count)||0),0);$("#batch-summary").textContent=`將記錄 ${state.selected.size} 份標準的人工確認，包含 ${unresolved} 個待處理原文項目。請先從各份文件的「查看／確認」檢查來源、獨立項目與待處理提示。`;$("#batch-reviewer").value=state.reviewer;$("#batch-note").value="";$("#batch-ack").checked=false;showDialog("batch-dialog");});
 handle("#batch-form","submit",e=>{e.preventDefault();return busy($('button[type=submit]',e.target),async()=>{const reviewer=$("#batch-reviewer").value.trim();const data=await post("/api/v2/library/confirm",{documents:[...state.selected.values()].map(d=>({id:d.id,expected_version:d.version})),reviewer,note:$("#batch-note").value.trim(),acknowledge_warnings:$("#batch-ack").checked});rememberReviewer(reviewer);showDialog("batch-dialog",false);await loadLibrary();notify(`勾選標準的確認已儲存。${data.errors?.length?asText(data.errors):"未解析的項目仍保留在後續分析。"}`,!!data.errors?.length);});});
 handle("#document-extract","click",e=>busy(e.currentTarget,async()=>{const doc=state.document;if(doc.item_count&&!window.confirm("重新抽取會建立新項目版本，這份文件需要重新人工確認。既有分析快照與歷程仍會保留。要繼續嗎？"))return;const job=await post(`/api/v2/documents/${ident(doc.id)}/extract`,{force:!!doc.item_count});setMonitor("job",job);showDialog("document-dialog",false);notify("正在抽取獨立項目，完成後請重新開啟文件核對。已在上方顯示執行現況。");await Promise.all([loadLibrary(),loadProducts()]);}));
 handle("#document-refresh","click",()=>refreshDocument());handle("#document-job","click",()=>showDocumentJob(state.document?.job_id));
 handle("#source-search","input",()=>renderSources());handle("#item-kind","change",()=>{state.offsets.items=0;return loadItems();});handle("#item-search","input",debounce(()=>{state.offsets.items=0;return loadItems();}));
 handle("#metadata-form","submit",e=>{e.preventDefault();return busy($('button[type=submit]',e.target),async()=>{const doc=state.document,reviewer=$("#metadata-reviewer").value.trim();await api(`/api/v2/documents/${ident(doc.id)}`,{method:"PATCH",body:JSON.stringify({expected_version:doc.version,reviewer,note:$("#metadata-note").value.trim(),metadata:Object.fromEntries(["category","version","region","scope"].map(k=>[k,$(`#metadata-${k}`).value.trim()]))})});rememberReviewer(reviewer);await refreshDocument();notify("文件範圍與版本資訊已記錄，請重新確認此份文件。");});});
 handle("#document-confirm-form","submit",e=>{e.preventDefault();return busy($("#document-confirm"),async()=>{const doc=state.document,reviewer=$("#document-reviewer").value.trim();await post(`/api/v2/documents/${ident(doc.id)}/confirm`,{expected_version:doc.version,reviewer,note:$("#document-note").value.trim(),acknowledge_warnings:$("#document-ack").checked});rememberReviewer(reviewer);await refreshDocument();notify("文件確認與覆核人員已記錄。待處理原文仍會列入風險檢查。");});});
 handle("#document-audit-load","click",()=>loadDocumentAudit());
 handle("#item-add","click",()=>{$("#item-editors").insertAdjacentHTML("beforeend",editorMarkup({...state.item,name:""},$$(".item-editor").length));});
 handle("#item-form","submit",e=>{e.preventDefault();return busy($('button[type=submit]',e.target),async()=>{const doc=state.document,item=state.item,reviewer=$("#item-reviewer").value.trim(),items=readEditors();const body={expected_version:doc.version,reviewer,note:$("#item-note").value.trim(),...(state.split?{items}:{item:items[0]})};await api(`/api/v2/documents/${ident(doc.id)}/items/${ident(item.id)}${state.split?"/split":""}`,{method:state.split?"POST":"PUT",body:JSON.stringify(body)});rememberReviewer(reviewer);showDialog("item-dialog",false);await refreshDocument();notify("項目與來源變更已保存；請重新確認此份文件後再建立新分析。");});});
 handle("#analysis-form","submit",e=>{e.preventDefault();return busy($("#analysis-start"),async()=>{if(!state.product?.confirmed)throw new Error("請先選取一份已完成抽取並人工確認的產品。");if(!state.settings.model){openSettings();throw new Error("請先設定本機模型。");}const data=await post("/api/v2/analyses",{name:$("#analysis-name").value.trim(),product_id:state.product.id,library_ids:[],context:Object.fromEntries(["purpose","environment","market","notes"].map(k=>[k,$(`#context-${k}`).value.trim()])),comparison_mode:$("#comparison-mode").value});state.decisions.clear();await openAnalysis(data.id);await loadAnalyses();notify("全庫初篩已啟動。所有標準預設保留，完成後請確認相關性與適用條件。");});});
