 handle("#review-form","submit",e=>{e.preventDefault();return busy($('button[type=submit]',e.target),async()=>{const r=state.result,id=state.analysis?.id,decision=$("#review-decision").value,reviewer=$("#review-reviewer").value.trim(),risk=$("#review-risk").value,note=$("#review-note").value.trim();if((decision!=="confirmed"||risk!==riskOf(r))&&!note)throw new Error("修正判定、調整風險或重新開啟時，請填寫理由。");const body={expected_version:r.review?.version||0,decision,final_status:decision==="changed"?$("#review-status").value:effective(r),reviewer,note};if(decision!=="reopened"&&risk!==riskOf(r))body.risk_level=risk;await post(`/api/v2/analyses/${ident(id)}/results/${ident(r.id)}/reviews`,body);rememberReviewer(reviewer);await openResult(r.id);await refreshAnalysis("results");notify("人工判定與確認歷程已儲存。");});});
