 handle("#connection-test","click",e=>busy(e.currentTarget,async()=>{$("#connection-result").textContent="正在連線本機模型服務…";try{const data=await post("/api/connection",{settings:settingsInput()});$("#model-options").innerHTML=list(data.models).map(m=>`<option value="${esc(m.id)}"></option>`).join("");if(!$("#setting-model").value&&data.models?.length)$("#setting-model").value=data.models[0].id;$("#connection-result").textContent=`${data.message||"連線成功"} · 找到 ${data.models?.length||0} 個模型。請儲存設定。`;}catch(error){$("#connection-result").textContent=error.message;throw error;}}));
 handle("#settings-form","submit",e=>{e.preventDefault();return busy($('button[type=submit]',e.target),async()=>{state.settings=await api("/api/settings",{method:"PUT",body:JSON.stringify(settingsInput())});$("#model-badge").textContent=state.settings.model?`本機模型：${state.settings.model}`:"尚未設定模型";showDialog("settings-dialog",false);notify("模型設定已儲存。新建立的工作會採用這組設定。");});});
