async function refreshAnalysis(panel) {if(!state.analysis)return;const id=state.analysis.id,data=await api(`/api/v2/analyses/${ident(id)}`);if(state.analysis?.id!==id)return;state.analysis=data;if(state.monitor?.id===id){state.monitor.data=data;state.offline="";recordContact(data.server_time);renderMonitor();}renderAnalysisMeta();if(panel==="screening")await loadScreening();if(panel==="results")await loadResults();}
async function init() {bind();renderSelected();const results=await Promise.allSettled([loadLibrary(),loadProducts(),loadAnalyses(),api("/api/settings")]);for(let i=0;i<results.length;i++){const result=results[i];if(result.status==="rejected")notify(result.reason.message,true);else if(i===3){state.settings=result.value;$("#model-badge").textContent=state.settings.model?`本機模型：${state.settings.model}`:"尚未設定模型";}}setInterval(renderMonitor,1000);}

async function showDocumentJob(id) {if(!id)return;const data=await api(`/api/v2/jobs/${ident(id)}`);showDialog("document-dialog",false);setMonitor("job",data);$("#execution").scrollIntoView({block:"start"});}
async function loadDocumentAudit() {const id=state.document?.id;if(!id)return;const stamp=requestStamp("documentAudit"),data=await api(`/api/v2/documents/${ident(id)}/audit?${pageQuery("documentAudit")}`);if(state.document?.id!==id||!currentStamp("documentAudit",stamp))return;$("#document-audit").innerHTML=renderAudit(data.items||data);pager("#document-audit-pagination",data,"documentAudit");}
async function loadAnalysisAudit() {const id=state.analysis?.id;if(!id)return;const stamp=requestStamp("audit"),data=await api(`/api/v2/analyses/${ident(id)}/audit?${pageQuery("audit")}`);if(state.analysis?.id!==id||!currentStamp("audit",stamp))return;$("#analysis-audit").innerHTML=renderAudit(data.items||data);pager("#audit-pagination",data,"audit");}
async function openLegacyImport() {const data=await api("/api/projects"),projects=list(data.items||data).filter(p=>!p.is_demo&&!p.demo);$("#legacy-project").innerHTML=projects.length?projects.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · ${esc(time(p.created_at))}</option>`).join(""):'<option value="">沒有可匯入的舊版專案</option>';$("#legacy-form button[type=submit]").disabled=!projects.length;showDialog("legacy-dialog");}
async function refreshSelectedSummaries() {let offset=0;const wanted=new Set(state.selected.keys());while(wanted.size){const data=await api(`/api/v2/library?offset=${offset}&limit=200`);for(const doc of list(data.items))if(wanted.has(doc.id)){state.selected.set(doc.id,doc);wanted.delete(doc.id);}offset+=data.limit||200;if(offset>=data.total)break;}renderSelected();}

const externalState={packages:[],current:null,preview:null};
function externalPath(suffix="") {return `/api/v2/documents/${ident(state.document.id)}/external${suffix}`;}
function clearExternalPreview() {$("#external-dialog .dialog-notice")?.remove();externalState.preview=null;$("#external-save").disabled=true;$("#external-preview-result").replaceChildren();}
async function openExternal() {
 if(state.document?.role!=="standard")return;
 $("#external-title").textContent=`外部萃取：${state.document.name}`;
 for(const id of ["external-create-reviewer","external-reviewer"])$(`#${id}`).value=state.reviewer;
 $("#external-public").checked=false;$("#external-ack").checked=false;$("#external-files").value="";
 clearExternalPreview();showDialog("external-dialog");await loadExternal();
}
async function loadExternal(prefer) {
 const id=state.document.id,data=await api(externalPath());if(state.document?.id!==id)return;
 externalState.packages=data.items;
 const selected=prefer||externalState.current?.id;
 $("#external-package").innerHTML=data.items.map(p=>`<option value="${esc(p.id)}">${esc(time(p.created_at))} · ${esc(p.id.slice(0,8))} · ${p.received_count}/${p.batch_count} 批${p.status==="activated"?" · 已套用":""}</option>`).join("")||'<option value="">請先建立萃取包</option>';
 if(data.items.some(p=>p.id===selected))$("#external-package").value=selected;
 renderExternal();
}
function renderExternal() {
 const p=externalState.packages.find(p=>p.id===$("#external-package").value);externalState.current=p;clearExternalPreview();
 const editable=p&&p.status==="collecting"&&!p.stale;
 $("#external-progress").textContent=p?`${p.status==="activated"?"已套用":p.stale?"文件已更新，此包不能套用，請建立新包":"等待外部結果"} · 已保存 ${p.received_count}/${p.batch_count} 批 · ${p.item_count} 項 · ${p.unresolved_count} 項待處理`:"尚未建立外部萃取包。";
 $("#external-missing").textContent=p?.missing_batches?.length?`尚缺：${p.missing_batches.slice(0,30).join("、")}${p.missing_batches.length>30?`……共 ${p.missing_batches.length} 批`:""}`:"";
 $("#external-download").hidden=!p;if(p)$("#external-download").href=externalPath(`/${ident(p.id)}/download`);
 $("#external-preview").disabled=!editable;$("#external-activate").disabled=!(editable&&p.received_count===p.batch_count);
}
function externalValues() {return {expected_version:externalState.current.version,reviewer:$("#external-reviewer").value.trim(),model_label:$("#external-model").value.trim(),note:$("#external-note").value.trim()};}
async function sendExternal(commit) {
 if(!$("#external-import-form").reportValidity())return;
 const p=externalState.current,files=Array.from($("#external-files").files||[]);
 if(!p||!files.length||files.length>50||files.reduce((n,f)=>n+f.size,0)>16*1024*1024)throw new Error("請選取 1–50 個 JSON，合計不超過 16 MB。");
 const values=externalValues();if(commit)values.preview_sha256=externalState.preview?.preview_sha256;
 const form=new FormData();form.append("values",JSON.stringify(values));for(const f of files)form.append("files",f);
 const data=await api(externalPath(`/${ident(p.id)}/${commit?"import":"preview"}`),{method:"POST",body:form},120000);
 rememberReviewer(values.reviewer);
 if(commit){await loadExternal(p.id);notify("本批結果已保存；全部收齊後請套用並人工核對。");return;}
 externalState.preview=data;
 $("#external-preview-result").innerHTML=`<div class="notice subtle"><strong>檢查通過，可保存 ${data.batches.length} 批</strong><p>${data.item_count} 項，${data.unresolved_count} 項待處理；${data.reused_count} 批與既有結果相同。</p>${data.replaced_batches.length?`<p>將取代已暫存批次：${esc(data.replaced_batches.join("、"))}</p>`:""}<p>來源文字能對應，不代表語意已確認。</p></div>${data.warnings.slice(0,30).map(w=>`<p class="helper">${esc(w)}</p>`).join("")}<h4>項目預覽（最多 10 筆）</h4>${data.sample_items.map(i=>`<article class="item-card">${tag(KIND[i.kind]||i.kind,i.kind)}<strong>${esc(i.name)}</strong><p>${esc(i.location)}</p><blockquote>${esc(i.quote)}</blockquote></article>`).join("")}`;
 $("#external-save").disabled=false;
}
function bindExternal() {
 handle("#document-external","click",()=>openExternal());
 handle("#external-refresh","click",()=>loadExternal());
 handle("#external-package","change",()=>renderExternal());
 for(const id of ["external-files","external-reviewer","external-model","external-note"])handle(`#${id}`,"input",()=>clearExternalPreview());
 handle("#external-create-form","submit",e=>{e.preventDefault();return busy($('button[type=submit]',e.target),async()=>{
  const data=await post(externalPath(),{expected_version:state.document.version,reviewer:$("#external-create-reviewer").value.trim(),acknowledge_public:$("#external-public").checked,blocks_per_batch:Number($("#external-batch-size").value)});
  rememberReviewer($("#external-create-reviewer").value);await loadExternal(data.id);$("#external-download").click();notify("萃取包已建立。解壓後將 PROMPT.md、source.json、schema 與指定批次交給 ChatGPT。");
 });});
 handle("#external-import-form","submit",e=>{e.preventDefault();return busy($("#external-preview"),()=>sendExternal(false),"核對原文中…");});
 handle("#external-save","click",e=>busy(e.currentTarget,async()=>{await sendExternal(true);},"保存中…").finally(()=>{$("#external-save").disabled=!externalState.preview;}));
 handle("#external-activate-form","submit",e=>{e.preventDefault();return busy($("#external-activate"),async()=>{
  const p=externalState.current,reviewer=$("#external-reviewer").value.trim(),note=$("#external-note").value.trim();
  if(!reviewer||!note)throw new Error("請填寫上方的匯入人員與操作備註。");
  await post(externalPath(`/${ident(p.id)}/activate`),{expected_version:p.version,reviewer,note,acknowledge_warnings:$("#external-ack").checked});
  rememberReviewer(reviewer);showDialog("external-dialog",false);await refreshDocument();notify("外部結果已套用為新項目版本。請核對原文、條件與待處理項目，再確認此份文件。");
 });});
}

const preparedState={preview:null};
function clearPrepared() {
 preparedState.preview=null;$("#prepared-save").disabled=true;$("#prepared-result").innerHTML="";
 $("#prepared-ack").checked=false;
}
async function importProgress(selector, caption, work) {
 const target=$(selector),started=Date.now();
 const update=()=>{target.textContent=`${caption} · 已等待 ${Math.floor((Date.now()-started)/1000)} 秒；完成後自動顯示結果。`;};
 update();const timer=setInterval(update,1000);
 try{const result=await work();target.textContent="檢查完成。";return result;}
 catch(error){target.textContent=error.message;throw error;}
 finally{clearInterval(timer);}
}
async function sendPrepared(commit) {
 if(!$("#prepared-form").reportValidity())return;
 if(commit&&!$("#prepared-ack").checked)throw new Error("請先勾選原始規範核對提醒。");
 const mode=$("#prepared-mode").value,values={reviewer:$("#prepared-reviewer").value.trim(),
  model_label:$("#prepared-model").value.trim(),note:$("#prepared-note").value.trim(),
  acknowledge_warnings:$("#prepared-ack").checked};
 if(commit)values.preview_sha256=preparedState.preview?.preview_sha256;
 const operation=commit?"import":"preview";let path,body;
 if(mode==="link"){
  Object.assign(values,{url:$("#prepared-url").value.trim(),filename:$("#prepared-filename").value.trim()});
  path=`/api/v2/library/standalone-link/${operation}`;body=JSON.stringify(values);
 }else{
  const file=$("#prepared-file").files[0];
  if(!file||file.size>16*1024*1024)throw new Error("請選擇一份 16 MB 以內的完整成果 JSON。");
  path=`/api/v2/library/standalone/${operation}`;body=new FormData();body.append("values",JSON.stringify(values));body.append("file",file);
 }
 const data=await importProgress("#prepared-status",mode==="link"?"下載並核對成果中":"核對成果中",()=>api(path,{method:"POST",body},120000));
 rememberReviewer(values.reviewer);
 if(commit){clearPrepared();showDialog("prepared-dialog",false);await loadLibrary();await openDocument(data.document.id);
  notify(data.reused?"相同成果已在文件庫，已開啟既有項目與確認紀錄。":"成果已匯入。請核對原始規範、轉錄範圍及每項要求，再確認文件。");return;}
 preparedState.preview=data;
 $("#prepared-result").innerHTML=`<div class="notice subtle"><strong>${esc(data.name)}</strong><p>${data.block_count} 個原文區塊 · ${data.item_count} 個項目 · ${data.unresolved_count} 個待處理</p><p>${data.coverage.status==="complete"?"外部聲明已完整處理，仍待人工確認":"外部聲明尚未完成：匯入後不能確認供分析使用"}${data.reused?" · 相同成果已在文件庫，將開啟既有紀錄":""}</p></div>${data.warnings.slice(0,30).map(w=>`<p class="helper">${esc(w)}</p>`).join("")}<h3>項目預覽（最多 10 筆）</h3>${data.sample_items.map(i=>`<article class="item-card">${tag(KIND[i.kind]||i.kind,i.kind)}<strong>${esc(i.name)}</strong><p>${esc(i.location)}</p><blockquote>${esc(i.quote)}</blockquote></article>`).join("")}`;
 $("#prepared-save").disabled=false;
}
function bindLinkImport() {
 handle("#library-link-form","submit",e=>{e.preventDefault();return busy($('button[type=submit]',e.target),async()=>{
  const data=await importProgress("#library-link-status","下載並解析規範中",()=>api("/api/v2/library/link",{method:"POST",body:JSON.stringify({url:$("#library-link-url").value.trim(),filename:$("#library-link-filename").value.trim()})},120000));
  state.selected.set(data.id,data);await loadLibrary();await openDocument(data.id);
  $("#library-link-status").textContent=data.reused?"已找到相同文件，開啟既有紀錄。":"規範已匯入，請接著抽取項目或交給外部模型整理。";
 },"下載中…");});
 handle("#prepared-open","click",()=>{clearPrepared();$("#prepared-reviewer").value=state.reviewer;
  $("#prepared-status").textContent="選擇成果來源並填寫人員與模型，先檢查預覽。";showDialog("prepared-dialog");});
 handle("#prepared-mode","change",()=>{
  const link=$("#prepared-mode").value==="link";$("#prepared-file-field").hidden=link;$("#prepared-link-fields").hidden=!link;
  $("#prepared-file").required=!link;$("#prepared-file").disabled=link;$("#prepared-url").required=link;$("#prepared-url").disabled=!link;clearPrepared();
 });
 for(const id of ["prepared-file","prepared-url","prepared-filename","prepared-reviewer","prepared-model","prepared-note"])handle(`#${id}`,"input",clearPrepared);
 handle("#prepared-form","submit",e=>{e.preventDefault();return busy($("#prepared-preview"),()=>sendPrepared(false),"檢查中…");});
 handle("#prepared-save","click",e=>busy(e.currentTarget,()=>sendPrepared(true),"匯入中…").finally(()=>{$("#prepared-save").disabled=!preparedState.preview;}));
}

init().catch(error=>notify(error.message,true));
